import com.luci.pianoroom.*;
public final class BenchmarkSynthTest {
 public static void main(String[]args)throws Exception{long bank=Synth.load(args[0]);if(bank==0)throw new AssertionError("bank");Synth synth=new Synth();try{for(int ch=0;ch<3;ch++){synth.setLayer(ch,bank,0);synth.setGain(ch,.28f);synth.channels[ch]=PianoSoundPresets.apply(synth.channels[ch],3);synth.channels[ch].chorus=15;}synth.channelChange(0);synth.channelChange(1);synth.channelChange(2);synth.backend(1);synth.latencyProfile(2);synth.manualBuffer(8);synth.automaticBuffer(false);synth.start();Thread.sleep(120);
  final boolean[] complete={false};PianoBenchmark b=new PianoBenchmark(new PianoBenchmark.Driver(){public void buffer(int n){synth.manualBuffer(n);}public void midi(int t,int k,int v){synth.midi(t,k,v);}public PianoBenchmark.Metrics metrics(){return synth.benchmarkMetrics();}public void finished(String report,int n){complete[0]=true;if(!report.contains("aceito"))throw new AssertionError("report");synth.panic();synth.manualBuffer(8);}},new int[]{4,2},"Simulated USB");long now=0;b.start(now);for(int phase=0;phase<2;phase++){now+=700;for(int i=0;i<96;i++){b.tick(now);now+=125;Thread.sleep(3);}if(!b.waiting)throw new AssertionError("await listening");b.rate(0,now);}if(!complete[0]||b.results.size()!=2||synth.manualBuffer()!=8||!synth.isRunning())throw new AssertionError("completion/restoration");if(synth.voicesNow().length!=8)throw new AssertionError("recycle diagnostics ABI");System.out.println("PASS: benchmark sequence drives actual three-channel Synth/JNI on simulated AAudio, native timing window, new diagnostics ABI, report and completion restore.");
 }finally{synth.close();Synth.freeBank(bank);}}
}
